import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createService} from '../src/service.mjs';
import {createCache} from '../src/cache.mjs';

test('hidden check', async () => {
  const cache = createCache(1000, () => 0);
  cache.set('a', 1);
  cache.delete('a');
  assert.equal(cache.get('a'), undefined);
  let calls = 0;
  const lookup = createService(async key => { calls++; return key + calls; }, {now: () => 0});
  assert.equal(await lookup('a'), 'a1');
  assert.equal(await lookup('b'), 'b2');
  lookup.invalidate('a');
  assert.equal(await lookup('a'), 'a3');
  assert.equal(await lookup('b'), 'b2');
});
